class Solution:
    def numOfMinutes(self, n: int, headID: int, manager: list[int], informTime: list[int]) -> int:
        org = defaultdict(list)
        for i in range(n):
            if manager[i] != -1:
                org[manager[i]].append(i)

        def dfs(u):
            if not org[u]:
                return informTime[u]

            time = 0
            for v in org[u]:
                time = max(time, dfs(v))

            return time + informTime[u]

        return dfs(headID)
